    struct Edge {
        int from, to;
        ll flow, capacity;
    };
    int s, t;
    vector<Edge> edges;
    vector<int> adj[MAX_SIZE];
    int dist[MAX_SIZE], visited[MAX_SIZE], current[MAX_SIZE];

    void clear() {
        edges.clear();
        for (int i = 0; i < MAX_SIZE; i++) {
            adj[i].clear();
        }
    }

    void addEdge(int u, int v, ll cap) {
        Edge e1 = {u, v, 0LL, cap};
        Edge e2 = {v, u, 0LL, 0};
        edges.push_back(e1);
        edges.push_back(e2);
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool buildLevelGraph() {
        memset(visited, 0, sizeof(visited));
        memset(dist, 0, sizeof(dist));
        queue<int> q;
        q.push(s);
        visited[s] = 1;
        dist[s] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i : adj[v]) {
                Edge &e = edges[i];
                int u = e.to;
                if (!visited[u] && e.capacity > e.flow) {
                    dist[u] = dist[v] + 1;
                    q.push(u);
                    visited[u] = 1;
                }
            }
        }
        return visited[t];
    }

    ll sendFlow(int v, ll flow) {
        if (v == t || flow == 0) return flow;
        ll total = 0;
        for (int &i = current[v]; i < (int)adj[v].size(); i++) {
            Edge &e = edges[adj[v][i]];
            if (dist[v] + 1 == dist[e.to]) {
                ll pushed = sendFlow(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[adj[v][i] ^ 1].flow -= pushed;
                    total += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
            }
        }
        return total;
    }

    ll maxFlow() {
        ll totalFlow = 0;
        while (buildLevelGraph()) {
            for (int i = 0; i < MAX_SIZE; i++) current[i] = 0;
            totalFlow += sendFlow(s, INF);
        }
        return totalFlow;
    }
};

