import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_SIZE = 7100;
    static final long INF = 1000000000L;

    static class Edge {
        int from, to;
        long flow, capacity;

        public Edge(int from, int to, long flow, long capacity) {
            this.from = from;
            this.to = to;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static class MaxFlowSolver {
        List<Edge> edges = new ArrayList<>();
        List<Integer>[] adj = new ArrayList[MAX_SIZE];
        int s, t;
        int[] dist = new int[MAX_SIZE];
        int[] visited = new int[MAX_SIZE];
        int[] current = new int[MAX_SIZE];

        public MaxFlowSolver() {
            for (int i = 0; i < MAX_SIZE; i++) {
                adj[i] = new ArrayList<>();
            }
        }

        void clear() {
            edges.clear();
            for (int i = 0; i < MAX_SIZE; i++) {
                adj[i].clear();
            }
        }

        void addEdge(int u, int v, long cap) {
            Edge e1 = new Edge(u, v, 0L, cap);
            Edge e2 = new Edge(v, u, 0L, 0);
            edges.add(e1);
            edges.add(e2);
            adj[u].add(edges.size() - 2);
            adj[v].add(edges.size() - 1);
        }

        boolean buildLevelGraph() {
            Arrays.fill(visited, 0);
            Arrays.fill(dist, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            visited[s] = 1;
            dist[s] = 0;
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int i : adj[v]) {
                    Edge e = edges.get(i);
                    int u = e.to;
                    if (visited[u] == 0 && e.capacity > e.flow) {
                        dist[u] = dist[v] + 1;
                        q.offer(u);
                        visited[u] = 1;
                    }
                }
            }
            return visited[t] == 1;
        }

        long sendFlow(int v, long flow) {
            if (v == t || flow == 0) return flow;
            long total = 0;
            for (int i = current[v]; i < adj[v].size(); i++) {
                int idx = adj[v].get(i);
                Edge e = edges.get(idx);
                if (dist[v] + 1 == dist[e.to]) {
                    long pushed = sendFlow(e.to, Math.min(flow, e.capacity - e.flow));
                    if (pushed > 0) {
                        e.flow += pushed;
                        edges.get(idx ^ 1).flow -= pushed;
                        total += pushed;
                        flow -= pushed;
                        if (flow == 0) break;
                    }
                }
                current[v]++;
            }
            return total;
        }

        long maxFlow() {
            long totalFlow = 0;
            while (buildLevelGraph()) {
                Arrays.fill(current, 0);
                totalFlow += sendFlow(s, INF);
            }
            return totalFlow;
        }
    }

    static char[][] mazeX = new char[14][14];
    static char[][] mazeY = new char[14][14];
    static boolean[][] visitedCells = new boolean[14][14];
    static int[][] distCells = new int[14][14];
    static int sizeN;
    static int[] targetIdx = new int[103];

    static int getIndex(int level, int x, int y) {
        return level * sizeN * sizeN + (x - 1) * sizeN + y;
    }

    static void BFS(int x, int y, int sizeN, boolean[][] visitedCells, int[][] distCells, char[][] mazeX) {
        for (int i = 0; i < 14; i++) {
            Arrays.fill(distCells[i], 111);
        }
        Queue<int[]> q = new LinkedList<>();
        distCells[x][y] = 0;
        q.offer(new int[]{x, y});
        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int cx = p[0], cy = p[1], d = distCells[cx][cy];
            if (visitedCells[cx][cy]) continue;
            visitedCells[cx][cy] = true;
            for (int i = 0; i < 4; i++) {
                int tx = cx + dx[i], ty = cy + dy[i];
                if (tx <= 0 || tx > sizeN || ty <= 0 || ty > sizeN || visitedCells[tx][ty] || mazeX[tx][ty] == 'Y') continue;
                distCells[tx][ty] = d + 1;
                q.offer(new int[]{tx, ty});
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        sizeN = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= sizeN; i++) {
            String line = br.readLine();
            for (int j = 1; j <= sizeN; j++) {
                mazeX[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= sizeN; i++) {
            String line = br.readLine();
            for (int j = 1; j <= sizeN; j++) {
                mazeY[i][j] = line.charAt(j - 1);
            }
        }

        MaxFlowSolver solver = new MaxFlowSolver();
        solver.s = 0;
        solver.t = MAX_SIZE - 2;

        int zx = 0, zy = 0;
        outer:
        for (int i = 1; i <= sizeN; i++) {
            for (int j = 1; j <= sizeN; j++) {
                if (mazeX[i][j] == 'Z') {
                    zx = i;
                    zy = j;
                    break outer;
                }
            }
        }

        for (int i = 1; i <= sizeN * sizeN; i++) {
            targetIdx[i] = MAX_SIZE - 3 - (sizeN * sizeN - i);
        }

        boolean[][] visitedCellsBFS = new boolean[14][14];
        int[][] distCellsBFS = new int[14][14];
        BFS(zx, zy, sizeN, visitedCellsBFS, distCellsBFS, mazeX);

        for (int i = 1; i <= sizeN; i++) {
            for (int j = 1; j <= sizeN; j++) {
                if (mazeX[i][j] >= '0' && mazeX[i][j] <= '9') {
                    solver.addEdge(solver.s, getIndex(0, i, j), mazeX[i][j] - '0');
                }
                if (mazeY[i][j] >= '0' && mazeY[i][j] <= '9') {
                    solver.addEdge(targetIdx[getIndex(0, i, j)], solver.t, mazeY[i][j] - '0');
                }
                solver.addEdge(getIndex(0, i, j), targetIdx[getIndex(0, i, j)], INF);
            }
        }

        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};

        for (int i = 1; i <= t; i++) {
            for (int j = 1; j <= sizeN; j++) {
                for (int k = 1; k <= sizeN; k++) {
                    if (mazeX[j][k] == 'Y' || mazeX[j][k] == 'Z') continue;
                    for (int l = 0; l < 4; l++) {
                        int tx = j + dx[l], ty = k + dy[l];
                        if (tx >= 1 && tx <= sizeN && ty >= 1 && ty <= sizeN && mazeX[tx][ty] != 'Y' && mazeX[tx][ty] != 'Z') {
                            if (distCellsBFS[j][k] >= i && distCellsBFS[tx][ty] >= i) {
                                solver.addEdge(getIndex(i - 1, tx, ty), getIndex(i, j, k), INF);
                            }
                        }
                    }
                    solver.addEdge(getIndex(i, j, k), targetIdx[getIndex(0, j, k)], INF);
                }
            }
        }

        System.out.println(solver.maxFlow());
    }
}
